/**
 * Implements in memory building of the tar archive from a given module folder.
 *
 * NOTE: There is an intentional design decision not to run npm install here.
 *       We simply bundle the output of the module.
 *
 * (too many missing interfaces...)
 * @flow
 */

import archiver from 'archiver';
import createLog from 'silk-log';
import * as pkg from './package';
import fs from 'fs';
import path from 'path';
import tmp from './tmp';
import run from './run';
import eventToPromise from 'event-to-promise';

import type {PackageJSON} from '../package';
import type {Readable} from 'stream';

const log = createLog('bundle');

export const METADATA_PATH = '.node_modules_cache.json';

/**
 * Since we are rehydrating outside of the typical npm lifecycle hooks we must
 * manually trigger a rebuild if any of these hooks are present.
 */
const REBUILD_HOOKS = ['preinstall', 'install', 'postinstall'];

export default async function(modulePkg: PackageJSON, modulePath: string): Readable {
  let target = tmp();

  // move package.json over...
  fs.writeFileSync(path.join(target, 'package.json'), JSON.stringify(modulePkg));

  // Move npmrc over if it exists...
  let npmrcPath = path.join(modulePath, '.npmrc');
  if (fs.existsSync(npmrcPath)) {
    let npmrc = fs.readFileSync(npmrcPath);
    fs.writeFileSync(path.join(target, '.npmrc'), npmrc);
  }
  await run(`npm i --ignore-scripts`, { cwd: target });

  let nodeModules = path.join(target, 'node_modules');
  let archive = archiver.create('tar', {});

  // Strip out peerDependencies we won't cache those in this module.
  delete modulePkg.peerDependencies;
  // If these are missing it's okay...
  let optionals = modulePkg.optionalDependencies || {};

  let dependencies = pkg.dependencies(modulePkg);
  let metadata = { dependencies: [] };
  log.info(`Bundling: ${modulePath}`, dependencies);

  for (let dep of dependencies) {
    let depPath = path.join(nodeModules, dep);
    //let depPkg = require(path.join(depPath, 'package.json'));
    if (!fs.existsSync(depPath) && !optionals[dep]) {
      throw new Error(`Missing dependency in ${modulePath}: ${depPath}`);
    }
    metadata.dependencies.push(dep);
    log.info('Adding', depPath);
    archive.directory(depPath, `node_modules/${dep}`);
  }
  archive.append(JSON.stringify(metadata), {
    name: METADATA_PATH
  });
  archive.finalize();

  return archive;
}
